'use strict';
MODEL.ntp={name:pair('NTP four-timestamp offset calculation','NTP four-timestamp offset கணக்கீடு'),controls:[num('offset','Server clock offset (ms)','Server clock offset (ms)',40,-500,500),num('out','Outbound delay (ms)','செல்லும் delay (ms)',20,1,500),num('back','Return delay (ms)','திரும்பும் delay (ms)',20,1,500)],compute(p){const t1=1000,t2=t1+ +p.out+ +p.offset,t3=t2+5,t4=t1+ +p.out+5+ +p.back,theta=((t2-t1)+(t3-t4))/2,delay=(t4-t1)-(t3-t2);return{nodes:['Client clock','Variable path','Server clock'],events:[event('Record four timestamps','நான்கு timestamps பதிவு',`T1=${t1}, T2=${t2}, T3=${t3}, T4=${t4} ms; server processing takes 5 ms.`,`T1=${t1}, T2=${t2}, T3=${t3}, T4=${t4} ms; server processing 5 ms எடுக்கிறது.`,0,2,{T1:t1,T2:t2,T3:t3,T4:t4}),event('Estimate offset and delay','Offset மற்றும் delay மதிப்பீடு',`Offset estimate=((T2−T1)+(T3−T4))/2=${theta} ms; path delay=${delay} ms.`,`Offset மதிப்பீடு=((T2−T1)+(T3−T4))/2=${theta} ms; path delay=${delay} ms.`,2,0,{estimatedOffset:theta,trueOffset:+p.offset,bias:theta- +p.offset,delay}),event('Observe asymmetric-path bias','Asymmetric-path bias கவனித்தல்','Changing one-way delay asymmetry biases the estimate; repeated samples alone do not prove symmetric paths.','One-way delay சமமில்லாவிட்டால் மதிப்பீடு மாறும்; repeated samples மட்டும் symmetric paths என்று நிரூபிக்காது.',0,1,{symmetryError:(+p.out- +p.back)/2})],limit:pair('One timing exchange only. Real NTP also filters samples, selects sources and disciplines a clock; PTP has different hardware and protocol mechanisms.','இது ஒரு timing exchange மட்டும். உண்மையான NTP samples filter செய்து sources தேர்வு செய்து clock discipline செய்கிறது; PTP-க்கு வேறு hardware/protocol mechanisms உண்டு.')};}};
MODEL.ssh={name:pair('SSH host-key verification','SSH host-key சரிபார்த்தல்'),controls:[bool('known','Trusted host key is already recorded','நம்பகமான host key ஏற்கெனவே பதிவு செய்யப்பட்டது',true),bool('changed','Presented host key changed','வழங்கப்பட்ட host key மாறியுள்ளது')],compute(p){const ok=p.known&&!p.changed;return{nodes:['SSH client','Untrusted link','SSH server'],events:[event('Negotiate and exchange host key','Negotiation மற்றும் host key exchange','The peer presents a host identity; encryption without identity checking can connect to the wrong peer.','Peer host identity வழங்குகிறது; identity சரிபார்க்காத encryption தவறான peer-க்கு இணைக்கலாம்.',2,0,{known:p.known,changed:p.changed}),event(ok?'Host identity matches':p.known?'Stop on key mismatch':'Verify fingerprint out of band',ok?'Host identity பொருந்துகிறது':p.known?'Key mismatch காரணமாக நிறுத்த':'Fingerprint-ஐ தனி trusted வழியில் சரிபார்க்க',ok?'A previously trusted host key matches. User authentication is a separate later step.':'Do not blindly remove known_hosts entries or trust an unseen fingerprint. Establish why the identity is new or changed.',ok?'முன்னர் நம்பிய host key பொருந்துகிறது. User authentication பின்னர் வரும் தனி படி.':'known_hosts entries-ஐ கண்மூடித்தனமாக நீக்காதீர்கள்; புதிய fingerprint நம்புமுன் identity ஏன் மாறியது என்று சரிபார்க்க வேண்டும்.',0,2,{identityAccepted:ok},!ok)]};}};
MODEL.mail={name:pair('Email routing and authentication signals','Email routing மற்றும் authentication signals'),controls:[bool('mx','Recipient MX is reachable','Recipient MX reach செய்ய முடிகிறது',true),bool('aligned','Aligned SPF or DKIM passes','Aligned SPF அல்லது DKIM வெற்றி',true),bool('strict','Receiver applies reject policy','Receiver reject policy பயன்படுத்துகிறது')],compute(p){const accepted=p.mx&&(!p.strict||p.aligned);return{nodes:['Sending MTA','DNS / MX','Receiving MTA'],events:[event('Resolve recipient mail routing','Recipient mail routing resolve செய்யப்படுகிறது','The sending MTA discovers recipient mail exchangers and attempts SMTP delivery.','Sending MTA recipient mail exchangers கண்டறிந்து SMTP delivery முயற்சிக்கிறது.',0,1,{MXReachable:p.mx}),event('Evaluate authentication and policy','Authentication மற்றும் policy மதிப்பீடு','SPF authenticates an envelope-related domain; DKIM verifies a signing domain. DMARC alignment relates results to the visible From domain.','SPF envelope தொடர்புடைய domain-ஐச் சரிபார்க்கிறது; DKIM signing domain-ஐ validate செய்கிறது. DMARC alignment இந்த results-ஐ visible From domain-உடன் தொடர்புபடுத்துகிறது.',0,2,{alignedPass:p.aligned,rejectPolicy:p.strict}),event(accepted?'Message accepted':'Message not accepted',accepted?'Message ஏற்கப்படுகிறது':'Message ஏற்கப்படவில்லை','Delivery acceptance is not proof that a person read the mail; IMAP/POP access is a separate mailbox interaction.','Delivery ஏற்றது மனிதர் mail படித்ததற்கான சான்றல்ல; IMAP/POP mailbox access தனி செயல்.',2,0,{accepted},!accepted)],limit:pair('Simplified delivery and policy decision; real SMTP retry/queueing, DNS failures, spam filtering and receiver DMARC discretion are omitted.','இது simplified delivery/policy முடிவு; SMTP retry/queueing, DNS failures, spam filtering, receiver DMARC discretion சேர்க்கப்படவில்லை.')};}};
MODEL.discovery={name:pair('mDNS discovery scope and guest isolation','mDNS discovery scope மற்றும் guest isolation'),controls:[bool('same','Devices share a link/VLAN','Devices ஒரே link/VLAN-ல் உள்ளன',true),bool('isolate','AP client isolation is enabled','AP client isolation செயலில் உள்ளது'),bool('service','Service advertises a matching instance','Service matching instance அறிவிக்கிறது',true)],compute(p){const visible=p.same&&!p.isolate&&p.service;return{nodes:['Phone','Local multicast','Desktop service'],events:[event('Browse service type','Service type தேடுதல்','A DNS-SD client can browse a service type with PTR records, then resolve SRV/TXT and A/AAAA data as needed.','DNS-SD client PTR records மூலம் service type தேடி, பின்னர் தேவைக்கேற்ப SRV/TXT மற்றும் A/AAAA resolve செய்யும்.',0,1,{query:'_http._tcp.local',mDNS:'224.0.0.251:5353'}),event(visible?'Service answer is visible':'No usable local answer',visible?'Service answer தெரிகிறது':'பயன்படுத்தக்கூடிய local answer இல்லை',visible?'The instance advertises an endpoint. The client must still connect and authenticate appropriately.':'A different VLAN, client isolation, absent advertiser or filtering can prevent discovery. A .local name does not cross arbitrary routers automatically.',visible?'Instance endpoint அறிவிக்கிறது. Client இன்னும் connect செய்து பொருத்தமாக authenticate செய்ய வேண்டும்.':'வேறு VLAN, client isolation, advertiser இல்லாமை அல்லது filtering discovery-ஐத் தடுக்கலாம். .local name தானாக எல்லா routers-ஐயும் கடக்காது.',2,0,{visible},!visible)]};}};
MODEL.rtc={name:pair('ICE candidate selection and relay fallback','ICE candidate தேர்வும் relay fallback-மும்'),controls:[bool('direct','Direct candidate checks succeed','Direct candidate checks வெற்றி',true),bool('relay','TURN allocation is available','TURN allocation கிடைக்கிறது',true)],compute(p){return{nodes:['Peer A','STUN / TURN','Peer B'],events:[event('Gather candidates','Candidates சேகரித்தல்','ICE gathers host, server-reflexive and relay candidates where available; signaling exchanges candidate information.','ICE கிடைக்கும் host, server-reflexive, relay candidates சேகரிக்கிறது; signaling candidate தகவல் பரிமாறுகிறது.',0,1,{directPossible:p.direct,relayAvailable:p.relay}),event(p.direct?'Select direct pair':p.relay?'Select relay pair':'No working pair',p.direct?'Direct pair தேர்வு':p.relay?'Relay pair தேர்வு':'வேலை செய்யும் pair இல்லை',p.direct?'Connectivity checks find a usable direct candidate pair.':p.relay?'A relay can carry traffic when a direct pair is unusable; relay capacity and authentication still matter.':'STUN alone does not guarantee connectivity through every NAT or firewall.',p.direct?'Connectivity checks usable direct candidate pair கண்டுபிடிக்கின்றன.':p.relay?'Direct pair வேலை செய்யாவிட்டால் relay traffic எடுத்துச் செல்லலாம்; relay capacity மற்றும் authentication அவசியம்.':'STUN மட்டும் எல்லா NAT/firewall வழியாக connectivity உறுதி செய்யாது.',0,p.direct?2:1,{path:p.direct?'DIRECT':p.relay?'RELAY':'FAILED'},!p.direct&&!p.relay)],limit:pair('Candidate-choice model only, not a browser WebRTC implementation. Consent, DTLS/SRTP and media codecs require further protocol state.','இது candidate-choice model; browser WebRTC implementation அல்ல. Consent, DTLS/SRTP, media codecs-க்கு கூடுதல் protocol state தேவை.')};}};
MODEL.tunnel={name:pair('Tunnel payload budget','Tunnel payload அளவு வரம்பு'),controls:[num('mtu','Outer IP / Ethernet payload budget','Outer IP / Ethernet payload வரம்பு',1500,576,9000),choice('kind','Encapsulation','Encapsulation வகை','gre',[['gre','GRE over IPv4','IPv4 மீது GRE'],['pppoe','PPPoE on Ethernet','Ethernet மீது PPPoE']])],compute(p){const overhead=p.kind==='gre'?24:8,budget=+p.mtu-overhead;return{nodes:['Inner packet','Encapsulation','Underlay'],events:[event('Account for headers','Headers அளவைக் கணக்கிடுதல்',p.kind==='gre'?'Minimal GRE (4 bytes) plus IPv4 (20 bytes) consumes 24 bytes of the outer IP packet budget.':'PPPoE (6 bytes) plus a two-byte PPP protocol field consumes 8 bytes of a 1500-byte Ethernet payload.',p.kind==='gre'?'Minimal GRE 4 bytes மற்றும் IPv4 20 bytes சேர்ந்து outer IP packet வரம்பில் 24 bytes எடுத்துக்கொள்கின்றன.':'PPPoE 6 bytes மற்றும் two-byte PPP protocol field சேர்ந்து Ethernet payload-ல் 8 bytes எடுத்துக்கொள்கின்றன.',0,1,{overhead}),event('Compute inner IP budget','Inner IP வரம்பைக் கணக்கிடுதல்',`Inner IP budget=${p.mtu}−${overhead}=${budget} bytes. GRE alone provides no encryption.`,`Inner IP வரம்பு=${p.mtu}−${overhead}=${budget} bytes. GRE தனியாக encryption தராது.`,1,2,{maxInnerIP:budget})],limit:pair('Minimal-header example. GRE options, outer IPv6, PPP negotiation and negotiated PPPoE extensions can change the budget.','இது minimal-header example. GRE options, outer IPv6, PPP negotiation மற்றும் PPPoE extensions அளவை மாற்றலாம்.')};}};
MODEL.multicast={name:pair('Multicast (S,G) membership, tree and RPF journey','Multicast (S,G) membership, tree மற்றும் RPF பயணம்'),controls:[bool('join','Receiver reports membership','Receiver membership report செய்கிறது',true),bool('ssm','Use source-specific (S,G)','Source-specific (S,G) பயன்படுத்த',true),bool('route','PIM tree state is available','PIM tree state கிடைக்கிறது',true),bool('rpf','Packet arrives on the RPF interface','Packet RPF interface-ல் வருகிறது',true)],compute(p){const G=p.ssm?'232.1.1.1':'239.1.1.1',S='192.0.2.10',tree=p.ssm?`(${S},${G})`:`(*,${G})`,forward=p.join&&p.route&&p.rpf,e=[event(p.join?'Report receiver interest':'No receiver report',p.join?'Receiver interest report செய்யப்படுகிறது':'Receiver report இல்லை',p.ssm?`IGMPv3 INCLUDE {${S}} requests channel (${S},${G}) on the receiver LAN.`:`IGMP/MLD reports Any-Source interest for group ${G}; this is local membership, not the routed tree.`,p.ssm?`IGMPv3 INCLUDE {${S}} receiver LAN-ல் channel (${S},${G}) கேட்கிறது.`:`IGMP/MLD group ${G}-க்கு Any-Source interest report செய்கிறது; இது local membership, routed tree அல்ல.`,3,2,{group:G,source:p.ssm?S:'ANY',filter:p.ssm?'INCLUDE':'EXCLUDE {}',membership:p.join},!p.join)];if(p.join)e.push(event(p.route?'Build forwarding state':'PIM state missing',p.route?'Forwarding state உருவாக்குதல்':'PIM state இல்லை',p.ssm?`The last-hop router joins toward source ${S}; ordinary SSM delivery does not require an ASM RP.`:`The last-hop router builds ${tree} state toward the RP; it may later switch traffic to an (S,G) shortest-path tree.`,p.ssm?`Last-hop router source ${S} நோக்கி join செய்கிறது; ordinary SSM delivery-க்கு ASM RP தேவையில்லை.`:`Last-hop router RP நோக்கி ${tree} state உருவாக்குகிறது; பின்னர் traffic (S,G) shortest-path tree-க்கு மாறலாம்.`,2,1,{tree,join:p.route?'UPSTREAM':'ABSENT',RPFSource:p.ssm?S:'RP'},!p.route));if(p.join&&p.route)e.push(event(p.rpf?'RPF check passes':'RPF check drops packet',p.rpf?'RPF check வெற்றி':'RPF check packet-ஐ drop செய்கிறது',p.rpf?'The data packet arrived on the interface selected toward the source/tree root.':'The packet arrived on a different interface from the multicast RPF choice, so it is rejected even if unicast ping works.',p.rpf?'Data packet source/tree root நோக்கி selected interface-ல் வந்துள்ளது.':'Packet multicast RPF choice-க்கு வேறு interface-ல் வந்ததால் unicast ping வேலை செய்தாலும் reject ஆகிறது.',0,1,{sourceIP:S,destinationIP:G,UDP:'5000→5000',incomingInterface:p.rpf?'RPF-EXPECTED':'RPF-WRONG',RPF:p.rpf?'PASS':'FAIL'},!p.rpf));e.push(event(forward?'Replicate to joined receiver LAN':'No downstream delivery',forward?'Joined receiver LAN-க்கு replicate':'Downstream delivery இல்லை',forward?'The last-hop router places one copy on the eligible outgoing interface; the application must still be bound to the matching UDP port.':'Delivery requires receiver membership, routed tree state and a passing RPF check at the same time.',forward?'Last-hop router eligible outgoing interface-ல் ஒரு copy வைக்கிறது; application matching UDP port-க்கு bind ஆக வேண்டும்.':'Delivery-க்கு receiver membership, routed tree state, RPF pass மூன்றும் ஒரே நேரத்தில் தேவை.',2,3,{outgoingInterface:forward?'Receiver-LAN':'NONE',applicationPort:5000,delivered:forward},!forward));return{nodes:['Source S','Upstream / RP','Last-hop router','Receiver app'],events:e,metrics:[['Channel',p.ssm?`(${S}, ${G})`:`(*, ${G})`],['RPF result',p.rpf?'PASS':'FAIL'],['Delivery',forward?'YES':'NO']],limit:pair('State-driven teaching journey for one source, group and receiver LAN. It does not emulate every IGMPv3/MLDv2 timer, PIM register/SPT transition, Assert election, snooping implementation or packet replication detail.','ஒரு source, group, receiver LAN-க்கான state-driven teaching journey. எல்லா IGMPv3/MLDv2 timers, PIM register/SPT transition, Assert election, snooping implementation, replication details emulate செய்யாது.')};}};
MODEL.mpls={name:pair('MPLS L3VPN two-label packet journey','MPLS L3VPN two-label packet பயணம்'),controls:[num('transport','Ingress transport label','Ingress transport label',16000,16,1048575),num('vpn','VPN service label','VPN service label',24000,16,1048575),bool('php','Use penultimate-hop popping','Penultimate-hop popping பயன்படுத்த',true),bool('imported','Destination VRF imports the route','Destination VRF route-ஐ import செய்கிறது',true)],compute(p){const t=+p.transport,v=+p.vpn,swapped=t+50,delivered=p.imported,e=[event('Classify in Red VRF and push two labels','Red VRF-ல் classify செய்து இரண்டு labels push',`PE1 selects customer destination 10.20.0.8. It pushes VPN label ${v} with S=1, then transport label ${t} with S=0.`,`PE1 customer destination 10.20.0.8 தேர்வு செய்கிறது. VPN label ${v}-ஐ S=1 உடனும் transport label ${t}-ஐ S=0 உடனும் push செய்கிறது.`,0,1,{customerIP:'10.20.0.8',VRF:'RED',stack:[{label:t,S:0},{label:v,S:1}],addedBytes:8}),event('Swap the locally significant transport label','Locally significant transport label-ஐ swap',`The core LSR looks up top label ${t} and swaps it to ${swapped}. It does not inspect or change VPN label ${v}.`,`Core LSR top label ${t} lookup செய்து ${swapped}-க்கு swap செய்கிறது. VPN label ${v}-ஐ inspect/change செய்யாது.`,1,2,{incomingTop:t,outgoingTop:swapped,innerVPNLabel:v,operation:'SWAP'}),event(p.php?'Pop outer label at penultimate hop':'Preserve outer label to PE2',p.php?'Penultimate hop-ல் outer label pop':'PE2 வரை outer label வைத்திருத்தல்',p.php?`Implicit NULL signaling causes PHP; label 3 is not put on the wire. PE2 receives stack [${v}].`:`No PHP is modeled; PE2 receives [${swapped},${v}] and must remove the transport context first.`,p.php?`Implicit NULL signaling PHP ஏற்படுத்துகிறது; label 3 wire-ல் வராது. PE2 stack [${v}] பெறுகிறது.`:`PHP இல்லை; PE2 [${swapped},${v}] பெற்று transport context-ஐ முதலில் நீக்க வேண்டும்.`,2,3,{operation:p.php?'POP':'FORWARD',wireLabel3:false,stackAtPE2:p.php?[v]:[swapped,v]}),event(delivered?'VPN label selects Red VRF':'VPN route is not imported',delivered?'VPN label Red VRF-ஐ தேர்வு செய்கிறது':'VPN route import ஆகவில்லை',delivered?`PE2 maps VPN label ${v} to the Red VRF, pops it, and forwards the unchanged customer IP packet.`:'The transport LSP can reach PE2, but missing RT import/service state prevents installation and customer delivery.',delivered?`PE2 VPN label ${v}-ஐ Red VRF-க்கு map செய்து pop செய்து unchanged customer IP packet-ஐ forward செய்கிறது.`:'Transport LSP PE2-ஐ அடைந்தாலும் missing RT import/service state customer delivery-ஐத் தடுக்கிறது.',3,3,{VPNLabel:v,VRF:delivered?'RED':'NONE',routeTarget:'64496:100',delivered,encryption:false},!delivered)];return{nodes:['PE1 / Red VRF','Core LSR','Penultimate LSR','PE2 / Red VRF'],events:e,metrics:[['Initial label stack',`[${t}, ${v}]`],['Stack overhead','8 bytes'],['Customer delivery',delivered?'YES':'NO']],limit:pair('One L3VPN teaching path with fixed customer IP and illustrative locally assigned labels. It omits label-distribution protocol details, ECMP, entropy labels, QoS/TTL modes and inter-provider options. MPLS is not encryption.','Fixed customer IP மற்றும் illustrative local labels கொண்ட ஒரு L3VPN teaching path. Label-distribution details, ECMP, entropy labels, QoS/TTL modes, inter-provider options சேர்க்கப்படவில்லை. MPLS encryption அல்ல.')};}};
MODEL.nat64={name:pair('DNS64 synthesis and NAT64 translation','DNS64 synthesis மற்றும் NAT64 translation'),controls:[bool('aaaa','An actual AAAA record exists','உண்மையான AAAA record உள்ளது'),bool('translator','NAT64 route and translator available','NAT64 route மற்றும் translator கிடைக்கிறது',true)],compute(p){const e=[event('Resolve IPv6 destination','IPv6 destination resolve செய்யப்படுகிறது',p.aaaa?'Use the actual AAAA answer; synthesis is not required in this simple case.':'DNS64 can synthesize an AAAA from an IPv4 A record when policy permits.',p.aaaa?'உண்மையான AAAA answer பயன்படுத்தப்படுகிறது; இந்த நிலையில் synthesis தேவையில்லை.':'Policy அனுமதித்தால் IPv4 A record-இலிருந்து DNS64 AAAA synthesize செய்யலாம்.',0,1,{address:p.aaaa?'2001:db8::80':'64:ff9b::c000:0250'}),event(p.aaaa?'Native IPv6 path':p.translator?'Translate at NAT64':'No translator path',p.aaaa?'Native IPv6 பாதை':p.translator?'NAT64 translation செய்யப்படுகிறது':'Translator பாதை இல்லை',p.aaaa?'A native path needs its own IPv6 reachability.':'The well-known prefix encodes 192.0.2.80 in this /96 example, but a synthesized address alone cannot provide a translator or route.',p.aaaa?'Native path-க்கு தனி IPv6 reachability தேவை.':'இந்த /96 example-ல் well-known prefix 192.0.2.80 encode செய்கிறது; synthesized address மட்டும் translator அல்லது route உருவாக்காது.',1,2,{reachable:p.aaaa||p.translator},!p.aaaa&&!p.translator)];return{nodes:['IPv6 client','DNS64 / NAT64','IPv4 or IPv6 server'],events:e,limit:pair('Uses documentation addresses and the well-known NAT64 /96 prefix. DNSSEC-aware synthesis and other prefix lengths require additional rules.','Documentation addresses மற்றும் well-known NAT64 /96 prefix பயன்படுத்தப்படுகின்றன. DNSSEC-aware synthesis, மற்ற prefix lengths-க்கு கூடுதல் விதிகள் உண்டு.')};}};
MODEL.wifi={name:pair('Wi-Fi retries and airtime budget','Wi-Fi retries மற்றும் airtime வரம்பு'),controls:[num('bytes','Useful bytes per frame','Frame-ன் useful bytes',1500,100,1500),num('phy','Illustrative PHY rate (Mbit/s)','மாதிரி PHY rate (Mbit/s)',100,1,1200),num('retry','Extra transmission attempts','கூடுதல் transmission முயற்சிகள்',1,0,5)],compute(p){const transmission=+p.bytes*8/+p.phy,airtime=(transmission+100)*(1+ +p.retry),goodput=+p.bytes*8/airtime;return{nodes:['Wi-Fi station','Shared airtime','Access point'],events:[event('Serialize payload','Payload serialize செய்யப்படுகிறது',`Payload-only transmission time=${transmission.toFixed(2)} µs. This model adds a fixed 100 µs teaching overhead per attempt.`,`Payload-only transmission நேரம்=${transmission.toFixed(2)} µs. ஒவ்வொரு முயற்சிக்கும் fixed 100 µs teaching overhead சேர்க்கப்படுகிறது.`,0,1,{payloadMicroseconds:transmission}),event('Account for retries','Retries அளவைக் கணக்கிடுதல்',`Total modeled airtime=${airtime.toFixed(2)} µs; effective goodput=${goodput.toFixed(2)} Mbit/s.`,`கணக்கிட்ட airtime=${airtime.toFixed(2)} µs; effective goodput=${goodput.toFixed(2)} Mbit/s ஆகும்.`,0,2,{attempts:1+ +p.retry,goodputMbit:goodput})],limit:pair('Arithmetic airtime illustration, not an IEEE 802.11 PHY/MAC simulator. Fixed overhead is invented for teaching; contention, aggregation, rates and acknowledgements vary in real deployments.','இது arithmetic airtime விளக்கம்; IEEE 802.11 PHY/MAC simulator அல்ல. Fixed overhead கற்பித்தலுக்கான assumption; உண்மையில் contention, aggregation, rates, acknowledgements மாறும்.')};}};
MODEL.telemetry={name:pair('Counter delta and discontinuity','Counter delta மற்றும் discontinuity'),controls:[num('before','Earlier byte counter','முந்தைய byte counter',100000,0,1000000,1000),num('after','Later byte counter','பிந்தைய byte counter',160000,0,1000000,1000),num('seconds','Sampling interval (s)','Sampling interval (s)',5,1,60)],compute(p){const delta=+p.after- +p.before,valid=delta>=0;return{nodes:['Interface counter','Collector','Time-series store'],events:[event('Read two counter samples','இரண்டு counter samples படித்தல்','A cumulative byte counter needs an elapsed interval to produce a rate.','Cumulative byte counter-இலிருந்து rate பெற elapsed interval தேவை.',0,1,{before:+p.before,after:+p.after,seconds:+p.seconds}),event(valid?'Compute rate':'Mark discontinuity',valid?'Rate கணக்கிடப்படுகிறது':'Discontinuity குறிக்கப்படுகிறது',valid?`Delta=${delta} bytes; rate=${(delta*8/+p.seconds).toFixed(2)} bit/s.`:'A decreasing counter needs reset/wrap context; do not invent negative bandwidth.',valid?`Delta=${delta} bytes; rate=${(delta*8/+p.seconds).toFixed(2)} bit/s.`:'Counter குறைந்தால் reset/wrap context தேவை; negative bandwidth என்று உருவாக்கக்கூடாது.',1,2,{valid,rateBitPerSecond:valid?delta*8/+p.seconds:'UNKNOWN'})]};}};
MODEL.ftp={name:pair('FTP control and data channel reachability','FTP control மற்றும் data channel reachability'),controls:[bool('control','Control channel is reachable','Control channel reach செய்ய முடிகிறது',true),bool('data','Negotiated data endpoint is reachable','Negotiated data endpoint reach செய்ய முடிகிறது',true)],compute(p){const e=[event('Establish control channel','Control channel உருவாக்குதல்','FTP uses a control connection for commands; a separate negotiated connection carries file/listing data.','FTP commands-க்கு control connection பயன்படுத்துகிறது; தனியாக negotiate செய்த connection file/listing data எடுத்துச் செல்கிறது.',0,2,{control:p.control},!p.control)];if(p.control)e.push(event(p.data?'Data transfer can begin':'Control works but data stalls',p.data?'Data transfer தொடங்கலாம்':'Control வேலை செய்கிறது; data தடைபடுகிறது','Inspect active/passive mode, endpoint advertisement, firewall policy and TLS settings. SFTP is a different SSH-based protocol.','Active/passive mode, endpoint advertisement, firewall policy, TLS settings பார்க்கவும். SFTP வேறு SSH-based protocol.',0,2,{dataChannel:p.data},!p.data));return{nodes:['FTP client','Firewall / NAT','FTP server'],events:e};}};
MODEL.rto={name:pair('TCP RTT estimator and RTO backoff','TCP RTT estimator மற்றும் RTO backoff'),controls:[num('sample','First RTT sample (ms)','முதல் RTT sample (ms)',120,1,5000),num('second','Second RTT sample (ms)','இரண்டாம் RTT sample (ms)',180,1,5000),bool('timeout','Then simulate timeout','பின்னர் timeout உருவகப்படுத்த')],compute(p){const r=+p.sample,r2=+p.second,s0=r,v0=r/2,rto0=Math.max(1000,s0+4*v0),v1=.75*v0+.25*Math.abs(s0-r2),s1=.875*s0+.125*r2,rto1=Math.max(1000,s1+4*v1),e=[event('First unambiguous sample','முதல் தெளிவான sample',`SRTT=${r} ms; RTTVAR=${r}/2=${v0} ms; RTO=max(1000, SRTT+4×RTTVAR)=${rto0} ms.`,`கணக்கீடு: SRTT=${r} ms; RTTVAR=${r}/2=${v0} ms; RTO=max(1000, SRTT+4×RTTVAR)=${rto0} ms.`,0,2,{SRTT:s0,RTTVAR:v0,RTO:rto0}),event('Second sample updates variation first','இரண்டாம் sample: முதலில் variation',`RTTVAR=0.75×${v0}+0.25×|${s0}−${r2}|=${v1.toFixed(3)} ms, using the old SRTT.`,`பழைய SRTT பயன்படுத்தி RTTVAR=0.75×${v0}+0.25×|${s0}−${r2}|=${v1.toFixed(3)} ms.`,2,0,{RTTVAR:v1}),event('Update smoothed RTT and timeout','Smoothed RTT மற்றும் timeout புதுப்பித்தல்',`SRTT=0.875×${s0}+0.125×${r2}=${s1.toFixed(3)} ms; RTO=${rto1.toFixed(3)} ms.`,`SRTT=0.875×${s0}+0.125×${r2}=${s1.toFixed(3)} ms; RTO=${rto1.toFixed(3)} ms.`,0,2,{SRTT:s1,RTTVAR:v1,RTO:rto1})];if(p.timeout)e.push(event('Timeout: exponential backoff','Timeout: exponential backoff','The modeled sender doubles RTO after timeout. Ambiguous retransmitted samples are excluded unless a valid mechanism removes ambiguity.','Timeout-க்குப் பின் model RTO இரட்டிப்பாக்குகிறது. Ambiguity நீக்கும் mechanism இல்லையெனில் retransmitted samples RTT கணக்கில் சேர்க்கப்படாது.',0,2,{RTO:rto1*2,retransmitted:true}));return{nodes:['Sender','Measured path','Receiver'],events:e,limit:pair('RFC 6298 teaching equations, with negligible clock granularity and the recommended 1-second lower bound. Actual implementations may have different permitted clock and timer policies.','RFC 6298 teaching equations; clock granularity மிகச் சிறியது என்றும் பரிந்துரைக்கப்பட்ட 1-second lower bound என்றும் கருதப்படுகிறது. உண்மையான implementations-ல் clock/timer policies மாறலாம்.')};}};
MODEL.congestion={name:pair('Reno-style window growth and loss','Reno-style window வளர்ச்சியும் loss-மும்'),controls:[num('threshold','ssthresh (segments)','ssthresh (segments)',8,2,32),num('lossRound','Loss round (0 = no loss)','Loss round (0 = loss இல்லை)',4,0,8),bool('timeout','Use timeout instead of fast recovery','Fast recovery-க்கு பதில் timeout')],compute(p){let cwnd=1,threshold=+p.threshold;const e=[],bars=[];for(let round=1;round<=8;round++){const loss=round===+p.lossRound;if(loss){threshold=Math.max(2,Math.floor(cwnd/2));cwnd=p.timeout?1:threshold;}else cwnd=cwnd<threshold?Math.min(cwnd*2,threshold):cwnd+1;bars.push(cwnd);e.push(event(`RTT round ${round}`,`RTT சுற்று ${round}`,loss?`Loss response sets ssthresh=${threshold} and cwnd=${cwnd}.`:`No modeled loss: ${cwnd<=threshold?'slow-start growth toward threshold':'additive congestion-avoidance growth'}.`,loss?`Loss response மூலம் ssthresh=${threshold}, cwnd=${cwnd} ஆகிறது.`:`இந்தச் சுற்றில் loss இல்லை; ${cwnd<=threshold?'threshold நோக்கி slow-start வளர்ச்சி':'additive congestion-avoidance வளர்ச்சி'}.`,0,2,{cwnd,ssthresh:threshold,round},loss));}return{nodes:['Sender cwnd','Bottleneck','ACK clock'],events:e,bars,limit:pair('RTT-round Reno-style teaching approximation, not CUBIC or BBR and not a segment-accurate RFC 5681 implementation. Compare these families in the written chapter and real ss/iperf labs.','இது RTT-round Reno-style approximation; CUBIC அல்லது BBR அல்ல; segment-accurate RFC 5681 implementation அல்ல. அத்தியாயம் மற்றும் ss/iperf labs-ல் வேறுபாடுகளை ஒப்பிடுங்கள்.')};}};
function shortestPaths(edges,start){const d={A:Infinity,B:Infinity,C:Infinity,D:Infinity},prev={};d[start]=0;const unseen=new Set(Object.keys(d));while(unseen.size){const n=[...unseen].sort((a,b)=>d[a]-d[b])[0];unseen.delete(n);if(!Number.isFinite(d[n]))break;for(const [a,b,w]of edges){const other=a===n?b:b===n?a:null;if(other&&unseen.has(other)&&d[n]+w<d[other]){d[other]=d[n]+w;prev[other]=n;}}}return{d,prev};}
MODEL.ospf={name:pair('Link-state shortest-path recomputation','Link-state shortest-path மீண்டும் கணக்கிடுதல்'),controls:[num('cost','A–B cost','A–B cost',2,1,30),bool('failure','Fail B–D link','B–D link செயலிழக்கிறது')],compute(p){const edges=[['A','B',+p.cost],['A','C',5],['B','C',1],['C','D',6],...(!p.failure?[['B','D',2]]:[])],r=shortestPaths(edges,'A');let path=['D'],n='D';while(r.prev[n]){n=r.prev[n];path.unshift(n);}return{nodes:['A','B','C','D'],events:[event('Build a shared link-state graph','Link-state graph உருவாக்குதல்','Assume adjacency and LSA flooding have completed; link costs define the local topology.','Adjacency மற்றும் LSA flooding முடிந்துவிட்டதாகக் கருதுகிறோம்; link costs topology வரையறுக்கின்றன.',0,1,{edges:edges.length,failedBD:p.failure}),event('Run shortest-path calculation','Shortest-path கணக்கிடுதல்',`From A to D, shortest cost=${r.d.D}; path=${path.join(' → ')}.`,`A-இலிருந்து D வரை shortest cost=${r.d.D}; path=${path.join(' → ')}.`,0,3,{path:path.join(' → '),cost:r.d.D}),event('Install forwarding choice','Forwarding choice நிறுவுதல்','The route uses the next hop from the computed shortest path; a topology change can alter this choice.','கணக்கிட்ட shortest path-ன் next hop பயன்படுத்தப்படும்; topology மாறினால் choice மாறலாம்.',0,path[1]==='B'?1:2,{nextHop:path[1],cost:r.d.D})],columns:['Link','Cost'],rows:edges.map(([a,b,w])=>[a+'–'+b,String(w)]),limit:pair('This runs Dijkstra on a small graph. It does not emulate OSPF neighbor states, LSA sequence numbers, areas or convergence timers. The SVG lays out node labels, not physical cable geography.','இது சிறிய graph-ல் Dijkstra கணக்கிடுகிறது. OSPF neighbor states, LSA sequence, areas, convergence timers emulate செய்யாது. SVG node labels மட்டும் காட்டும்; cable geography அல்ல.')};}};
MODEL.stp={name:pair('Spanning-tree root and alternate path','Spanning-tree root மற்றும் alternate path'),controls:[bool('failure','Fail the direct root–B link','Direct root–B link செயலிழக்கிறது'),num('alternate','Alternate path cost','Alternate path cost',20,1,100)],compute(p){const direct=p.failure?Infinity:10,alternate=+p.alternate,chosen=direct<=alternate?'direct':'alternate';return{nodes:['Root switch','Switch A','Switch B'],events:[event('Elect root by bridge identity','Bridge identity மூலம் root தேர்வு','This setup fixes the lowest bridge ID at the root; other switches compare path costs to it.','இந்த setup-ல் குறைந்த bridge ID root ஆக நிர்ணயிக்கப்பட்டுள்ளது; மற்ற switches அதற்கான path cost ஒப்பிடுகின்றன.',0,1,{root:'Root switch'}),event('Compare root paths','Root paths ஒப்பிடுதல்',`Direct cost=${Number.isFinite(direct)?direct:'unavailable'}; alternate cost=${alternate}.`,`Direct cost=${Number.isFinite(direct)?direct:'கிடைக்கவில்லை'}; alternate cost=${alternate}.`,1,2,{direct:Number.isFinite(direct)?direct:'DOWN',alternate,selected:chosen}),event('Avoid a forwarding loop','Forwarding loop தவிர்க்கப்படுகிறது','Only the selected path is used toward the root; an eligible redundant path remains non-forwarding until needed.','Root நோக்கி selected path மட்டும் பயன்படுத்தப்படும்; தேவையில்லாத redundant path non-forwarding ஆக இருக்கும்.',chosen==='direct'?0:1,2,{forwarding:chosen,loopFree:true})],limit:pair('Illustrates path selection after convergence; not full STP/RSTP port-role election, BPDU processing or failover timing. Equal-cost tie-breakers are omitted.','Convergence-க்குப் பின் path selection மட்டும் காட்டப்படுகிறது; முழு STP/RSTP port-role election, BPDU processing, failover timing அல்ல. Equal-cost tie-breakers சேர்க்கப்படவில்லை.')};}};
MODEL.vxlan={name:pair('EVPN-controlled VXLAN packet journey','EVPN கட்டுப்படுத்தும் VXLAN packet பயணம்'),controls:[num('inner','Inner IP length (bytes)','Inner IP நீளம் (bytes)',1500,100,9000),num('underlay','Underlay IP MTU','Underlay IP MTU',1600,576,9500),bool('outer6','IPv6 outer header','IPv6 outer header பயன்படுத்த'),bool('tagged','Inner frame has 802.1Q tag','Inner frame-ல் 802.1Q tag உள்ளது'),bool('route','EVPN Type 2 route imports successfully','EVPN Type 2 route சரியாக import ஆகிறது',true)],compute(p){p={...p,route:p.route!==false};const outerSrc=p.outer6?'2001:db8:100::11':'192.0.2.11',outerDst=p.outer6?'2001:db8:100::12':'192.0.2.12',ipHeader=p.outer6?40:20,vlan=p.tagged?4:0,overhead=14+vlan+8+8+ipHeader,outer=+p.inner+overhead,fit=outer<=+p.underlay,e=[event(p.route?'Import EVPN Type 2 reachability':'Reject EVPN route at import policy',p.route?'EVPN Type 2 reachability-ஐ import செய்தல்':'EVPN route import policy-ல் reject',p.route?'VTEP A imports MAC 02:00:00:00:02:14 with RT 65000:5000, VNI 5000 and next hop 192.0.2.12. Underlay resolution and data-plane programming succeed.':'The route is received but RT 65000:5000 is not imported into the target MAC-VRF, so no remote-MAC forwarding entry is programmed.',p.route?'VTEP A MAC 02:00:00:00:02:14-ஐ RT 65000:5000, VNI 5000, next hop 192.0.2.12 உடன் import செய்கிறது. Underlay resolution மற்றும் data-plane programming வெற்றி.':'Route receive ஆனது; ஆனால் RT 65000:5000 target MAC-VRF-க்கு import ஆகவில்லை. Remote-MAC forwarding entry program ஆகாது.',3,1,{EVPNRouteType:2,routeTarget:'65000:5000',VNI:5000,remoteMAC:'02:00:00:00:02:14',nextHop:'192.0.2.12',imported:!!p.route},!p.route)];if(!p.route){e.push(event('Stop before VXLAN encapsulation','VXLAN encapsulation-க்கு முன் நிறுத்தம்','A bounded probe produces no UDP/4789 packet because destination overlay reachability was not installed.','Destination overlay reachability install ஆகாததால் bounded probe UDP/4789 packet உருவாக்காது.',1,1,{delivered:false,failureGate:'EVPN_RT_IMPORT',UDP4789Observed:false},true));return{nodes:['Host A','VTEP A','Underlay router','VTEP B / Host B'],events:e,metrics:[['Required underlay IP MTU',String(outer)],['Header overhead',String(overhead)],['Delivery','NO']],limit:pair('Known-unicast teaching path. Type 3 BUM replication, mobility and multihoming are explained in the lesson rather than emulated here.','Known-unicast teaching path. Type 3 BUM replication, mobility, multihoming lesson-ல் விளக்கப்படுகின்றன; இங்கு emulate செய்யப்படவில்லை.')};}e.push(event('Encapsulate the complete tenant frame','முழு tenant frame-ஐ encapsulate',`Inner Ethernet is 02:00:00:00:01:0a → 02:00:00:00:02:14 with ${p.tagged?'one 802.1Q tag':'no VLAN tag'}. VTEP A adds VXLAN I=1/VNI=5000, UDP 55001→4789 and outer ${p.outer6?'IPv6':'IPv4'} ${outerSrc}→${outerDst}.`,`Inner Ethernet 02:00:00:00:01:0a → 02:00:00:00:02:14; ${p.tagged?'ஒரு 802.1Q tag உள்ளது':'VLAN tag இல்லை'}. VTEP A VXLAN I=1/VNI=5000, UDP 55001→4789, outer ${p.outer6?'IPv6':'IPv4'} ${outerSrc}→${outerDst} சேர்க்கிறது.`,1,2,{innerSourceMAC:'02:00:00:00:01:0a',innerDestinationMAC:'02:00:00:00:02:14',VXLANFlags:'I=1',VNI:5000,UDP:'55001→4789',outerIP:outerSrc+'→'+outerDst,outerTTL:64,outerIPLength:outer,underlayMTU:+p.underlay,fits:fit}),event(fit?'Forward and rewrite outer Layer 2':'Drop at the MTU gate',fit?'Forward செய்து outer Layer 2 rewrite':'MTU gate-ல் drop',fit?'The router removes the received outer Ethernet header, decrements outer TTL 64→63 and writes next-hop outer MAC addresses. The inner frame, VNI and outer destination IP remain unchanged.':`Required outer IP length is ${outer} bytes, larger than underlay MTU ${p.underlay}. The VTEP must not fragment the VXLAN packet; useful PMTU signaling or a corrected MTU budget is required.`,fit?'Router received outer Ethernet header-ஐ நீக்கி outer TTL 64→63 ஆக்கி next-hop outer MAC addresses எழுதுகிறது. Inner frame, VNI, outer destination IP மாறாது.':`Required outer IP length ${outer} bytes; underlay MTU ${p.underlay}-ஐவிட பெரியது. VTEP VXLAN packet-ஐ fragment செய்யக்கூடாது; useful PMTU signaling அல்லது சரியான MTU budget தேவை.`,2,fit?3:2,fit?{outerEthernetBefore:'VTEP-A-MAC→R1-MAC',outerEthernetAfter:'R1-EGRESS-MAC→VTEP-B-NEXT-HOP-MAC',outerTTL:63,innerFrameChanged:false,VNI:5000}:{delivered:false,failureGate:'UNDERLAY_MTU',requiredMTU:outer,configuredMTU:+p.underlay,outerPacketSent:false},!fit));if(fit)e.push(event('Validate, decapsulate and deliver','Validate செய்து decapsulate செய்து deliver',`VTEP B validates I=1 and VNI 5000, strips outer Ethernet/${p.outer6?'IPv6':'IPv4'}/UDP/VXLAN, and delivers the unchanged inner frame to 02:00:00:00:02:14.`,`VTEP B I=1, VNI 5000 validate செய்து outer Ethernet/${p.outer6?'IPv6':'IPv4'}/UDP/VXLAN strip செய்து unchanged inner frame-ஐ 02:00:00:00:02:14-க்கு deliver செய்கிறது.`,3,3,{decapsulated:true,delivered:true,innerSourceMAC:'02:00:00:00:01:0a',innerDestinationMAC:'02:00:00:00:02:14',innerFrameChanged:false}));return{nodes:['Host A','VTEP A','Underlay router','VTEP B / Host B'],events:e,metrics:[['Required underlay IP MTU',String(outer)],['Header overhead',String(overhead)],['Delivery',fit?'YES':'NO']],limit:pair('Known-unicast teaching path with one routed underlay hop. It does not emulate BGP timers, Type 3 BUM replication, ECMP hashing, fragmentation, mobility or multihoming. Outer Ethernet remains outside the IP-MTU calculation.','ஒரு routed underlay hop கொண்ட known-unicast teaching path. BGP timers, Type 3 BUM replication, ECMP hashing, fragmentation, mobility, multihoming emulate செய்யப்படவில்லை. Outer Ethernet IP-MTU calculation-க்கு வெளியே உள்ளது.')};}};
MODEL.vpc={
 name:pair('VPC listener, health and two-connection packet journey','VPC listener, health மற்றும் இரு-connection packet பயணம்'),
 controls:[
  bool('route','Front-end route and listener are available','Front-end route மற்றும் listener கிடைக்கின்றன',true),
  bool('frontend','Front-end Security Group and Network ACL permit TCP/443','Front-end Security Group மற்றும் Network ACL TCP/443 permit செய்கின்றன',true),
  bool('health','GET /ready returns an accepted status','GET /ready accepted status தருகிறது',true),
  bool('backend','Backend route, policy and TCP/8080 listener work','Backend route, policy மற்றும் TCP/8080 listener வேலை செய்கின்றன',true),
  bool('returnAcl','Stateless return path permits ephemeral ports','Stateless return path ephemeral ports permit செய்கிறது',true)
 ],
 compute(p){
  p={...p,route:p.route!==false,frontend:p.frontend!==false,health:p.health!==false,backend:p.backend!==false,returnAcl:p.returnAcl!==false};
  const e=[event('Health probe samples the target','Health probe target-ஐ sample செய்கிறது',
   p.health?'At t=0 ms, ALB node 10.0.1.10:32000 opens TCP to 10.0.2.7:8080 and GET /ready returns HTTP 200. This independent connection marks the target eligible in the teaching state.':'At t=0 ms, GET /ready returns HTTP 503, so the target is unhealthy. A local loopback curl would not replace this remote observation.',
   p.health?'t=0 ms-ல் ALB node 10.0.1.10:32000, 10.0.2.7:8080-க்கு TCP open செய்கிறது; GET /ready HTTP 200 தருகிறது. இந்த independent connection teaching state-ல் target-ஐ eligible ஆக்குகிறது.':'t=0 ms-ல் GET /ready HTTP 503 தருவதால் target unhealthy. Local loopback curl இந்த remote observation-ஐ மாற்றாது.',
   1,3,{timeMs:0,flow:'10.0.1.10:32000→10.0.2.7:8080',HTTP:'GET /ready',status:p.health?200:503,targetHealth:p.health?'healthy':'unhealthy'},!p.health)];
  if(!p.health){
   e.push(event('Stop normal target selection','Normal target selection நிறுத்தம்','This model stops the normal selection path at TARGET_HEALTH. AWS ALB all-unhealthy fail-open behavior is documented in the lesson but intentionally not simulated as a safe delivery.','இந்த model normal selection path-ஐ TARGET_HEALTH-ல் நிறுத்துகிறது. AWS ALB all-unhealthy fail-open behavior lesson-ல் document செய்யப்பட்டுள்ளது; safe delivery போல இங்கு simulate செய்யப்படவில்லை.',1,1,{delivered:false,failureGate:'TARGET_HEALTH',documentedFailOpenRisk:true},true));
   return{nodes:['Internet client','Public ALB','VPC router / policy','Target app'],events:e,metrics:[['Client flow','198.51.100.20:53000 → 203.0.113.10:443'],['Backend flow','not opened'],['Delivery','NO']],limit:pair('One AWS ALB teaching deployment. Health thresholds, DNS address rotation, multiple nodes/AZs and fail-open forwarding are described but not emulated.','ஒரு AWS ALB teaching deployment. Health thresholds, DNS address rotation, multiple nodes/AZs, fail-open forwarding விவரிக்கப்படுகின்றன; emulate செய்யப்படவில்லை.')};
  }
  e.push(event(p.route?'Client reaches the HTTPS listener':'Route or listener stops the SYN',p.route?'Client HTTPS listener-ஐ அடைகிறது':'Route அல்லது listener SYN-ஐ நிறுத்துகிறது',
   p.route?'At t=100 ms, the client sends Ethernet/IP/TCP toward 203.0.113.10:443. Routers replace hop-local Layer-2 addresses and decrement IPv4 TTL; the end-to-listener tuple remains 198.51.100.20:53000→203.0.113.10:443.':'At t=100 ms, no usable route/listener path completes TCP/443; target health cannot repair the front-end gate.',
   p.route?'t=100 ms-ல் client Ethernet/IP/TCP-ஐ 203.0.113.10:443 நோக்கி அனுப்புகிறது. Routers hop-local Layer-2 addresses மாற்றி IPv4 TTL குறைக்கின்றன; end-to-listener tuple 198.51.100.20:53000→203.0.113.10:443 ஆகவே இருக்கும்.':'t=100 ms-ல் usable route/listener path TCP/443-ஐ complete செய்யாது; target health front-end gate-ஐ சரிசெய்யாது.',
   0,p.route?1:2,p.route?{timeMs:100,clientEthernet:'02:00:00:00:00:20→gateway-MAC',IP:'198.51.100.20→203.0.113.10',TCP:'53000→443',IPv4TTL:'64→63',layer2Rewritten:true}:{timeMs:100,delivered:false,failureGate:'FRONT_ROUTE_OR_LISTENER',SYNACKObserved:false},!p.route));
  if(!p.route)return{nodes:['Internet client','Public ALB','VPC router / policy','Target app'],events:e,metrics:[['Client flow','198.51.100.20:53000 → 203.0.113.10:443'],['Backend flow','not opened'],['Delivery','NO']],limit:pair('Documentation addresses represent roles, not stable ALB addresses. Provider internals and gateway NAT are abstracted.','Documentation addresses roles-ஐக் குறிக்கின்றன; stable ALB addresses அல்ல. Provider internals, gateway NAT abstract செய்யப்பட்டுள்ளன.')};
  e.push(event(p.frontend?'Permit TCP and terminate TLS':'Front-end policy rejects TCP/443',p.frontend?'TCP permit செய்து TLS terminate':'Front-end policy TCP/443-ஐ reject செய்கிறது',
   p.frontend?'At t=120 ms, front-end policy permits TCP/443. TLS 1.3 authenticates api.example.test and the listener decrypts HTTP GET /catalog before selecting target group web:8080.':'At t=120 ms, the Security Group or ordered Network ACL rejects the client conversation before TLS. No backend connection opens.',
   p.frontend?'t=120 ms-ல் front-end policy TCP/443 permit செய்கிறது. TLS 1.3 api.example.test-ஐ authenticate செய்து listener HTTP GET /catalog-ஐ decrypt செய்தபின் target group web:8080 தேரும்.':'t=120 ms-ல் Security Group அல்லது ordered Network ACL client conversation-ஐ TLS-க்கு முன் reject செய்கிறது. Backend connection open ஆகாது.',
   2,1,p.frontend?{timeMs:120,SecurityGroup:'ALLOW TCP/443',NetworkACL:'ALLOW both directions',TLS:'1.3 terminated',server_name:'api.example.test',HTTP:'GET /catalog',targetGroup:'web:8080'}:{timeMs:120,delivered:false,failureGate:'FRONT_POLICY',backendConnectionOpened:false},!p.frontend));
  if(!p.frontend)return{nodes:['Internet client','Public ALB','VPC router / policy','Target app'],events:e,metrics:[['Client flow','blocked before TLS'],['Backend flow','not opened'],['Delivery','NO']],limit:pair('The model combines Security Group and Network ACL into one front-policy switch; inspect them independently in a real investigation.','Model Security Group, Network ACL-ஐ ஒரு front-policy switch-ல் சேர்க்கிறது; உண்மை investigation-ல் தனித்தனியாக inspect செய்யுங்கள்.')};
  e.push(event(p.backend?'Open a distinct backend connection':'Backend route, policy or listener fails',p.backend?'தனி backend connection open செய்கிறது':'Backend route, policy அல்லது listener தோற்கிறது',
   p.backend?'At t=140 ms, the ALB originates TCP 10.0.1.10:41000→10.0.2.7:8080 and sends HTTP GET /catalog. This is not continuation of client TCP; target response returns to ALB port 41000.':'At t=140 ms, the selected healthy target cannot complete TCP/8080 because a backend route, target policy or process listener gate fails.',
   p.backend?'t=140 ms-ல் ALB TCP 10.0.1.10:41000→10.0.2.7:8080 originate செய்து HTTP GET /catalog அனுப்புகிறது. இது client TCP-ன் continuation அல்ல; target response ALB port 41000-க்கு திரும்பும்.':'t=140 ms-ல் backend route, target policy அல்லது process listener gate தோல்வியால் selected healthy target TCP/8080 complete செய்யாது.',
   1,p.backend?3:2,p.backend?{timeMs:140,IP:'10.0.1.10→10.0.2.7',TCP:'41000→8080',HTTP:'GET /catalog',newTCPConnection:true,targetSecurityGroup:'ALLOW source ALB-SG'}:{timeMs:140,delivered:false,failureGate:'BACKEND_ROUTE_POLICY_OR_LISTENER',targetHealthySample:true},!p.backend));
  if(!p.backend)return{nodes:['Internet client','Public ALB','VPC router / policy','Target app'],events:e,metrics:[['Client flow','TLS accepted'],['Backend flow','10.0.1.10:41000 → 10.0.2.7:8080 failed'],['Delivery','NO']],limit:pair('Health and request paths are sampled separately; a target can change after a successful probe.','Health மற்றும் request paths தனித்தனியாக sample செய்யப்படுகின்றன; successful probe பிறகு target மாறலாம்.')};
  e.push(event(p.returnAcl?'Target returns on the backend connection':'Stateless return ACL drops the backend reply',p.returnAcl?'Target backend connection-ல் response திருப்புகிறது':'Stateless return ACL backend reply-ஐ drop செய்கிறது',
   p.returnAcl?'At t=170 ms, target HTTP 200 returns only on the backend connection as 10.0.2.7:8080→10.0.1.10:41000. The ALB, not the Internet client, is this packet’s destination.':'At t=170 ms, a stateless Network ACL omits the required ephemeral return destination. Stateful Security Group tracking cannot override that separate subnet-boundary drop.',
   p.returnAcl?'t=170 ms-ல் target HTTP 200 backend connection-ல் மட்டும் 10.0.2.7:8080→10.0.1.10:41000 ஆக திரும்பும். இந்த packet-ன் destination ALB; Internet client அல்ல.':'t=170 ms-ல் stateless Network ACL required ephemeral return destination-ஐ omit செய்கிறது. Stateful Security Group tracking அந்த தனி subnet-boundary drop-ஐ override செய்யாது.',
   3,p.returnAcl?1:2,p.returnAcl?{timeMs:170,backendReply:'10.0.2.7:8080→10.0.1.10:41000',HTTPStatus:200,backendConnectionComplete:true}:{timeMs:170,delivered:false,failureGate:'STATELESS_RETURN_ACL',requiredDestinations:[41000,53000],SecurityGroupStateful:true},!p.returnAcl));
  if(p.returnAcl)e.push(event('ALB encrypts and delivers the client response','ALB encrypt செய்து client response deliver செய்கிறது',
   'At t=180 ms, the ALB maps the HTTP response to the separate front-end exchange, encrypts it in TLS and sends 203.0.113.10:443→198.51.100.20:53000. Transit routers again rewrite only hop-local Layer-2 headers.',
   't=180 ms-ல் ALB HTTP response-ஐ தனி front-end exchange-க்கு map செய்து TLS-ல் encrypt செய்து 203.0.113.10:443→198.51.100.20:53000 அனுப்புகிறது. Transit routers மீண்டும் hop-local Layer-2 headers மட்டும் rewrite செய்கின்றன.',
   1,0,{timeMs:180,backendReply:'10.0.2.7:8080→10.0.1.10:41000',frontReply:'203.0.113.10:443→198.51.100.20:53000',HTTPStatus:200,TLS:'encrypted to client',layer2Rewritten:true,delivered:true}));
  return{nodes:['Internet client','Public ALB','VPC router / policy','Target app'],events:e,metrics:[['Client flow','198.51.100.20:53000 → 203.0.113.10:443'],['Backend flow','10.0.1.10:41000 → 10.0.2.7:8080'],['Health flow','10.0.1.10:32000 → 10.0.2.7:8080'],['Delivery',p.returnAcl?'YES':'NO']],limit:pair('One illustrative AWS ALB request. It is not a provider emulator: DNS rotation, NAT internals, per-AZ nodes, HTTP/2 multiplexing, thresholds, retries and connection reuse are omitted.','ஒரு illustrative AWS ALB request. இது provider emulator அல்ல: DNS rotation, NAT internals, per-AZ nodes, HTTP/2 multiplexing, thresholds, retries, connection reuse சேர்க்கப்படவில்லை.')};
 }
};
MODEL.kubernetes={
 name:pair('Kubernetes Service, policy and VXLAN packet journey','Kubernetes Service, policy மற்றும் VXLAN packet பயணம்'),
 controls:[
  bool('dns','DNS egress and answer succeed','DNS egress மற்றும் answer வெற்றி',true),
  bool('ready','EndpointSlice has a ready backend','EndpointSlice-ல் ready backend உள்ளது',true),
  bool('egress','Client egress policy permits backend','Client egress policy backend-ஐ permit செய்கிறது',true),
  bool('ingress','Backend ingress policy permits client','Backend ingress policy client-ஐ permit செய்கிறது',true),
  num('underlay','Underlay IP MTU (bytes)','Underlay IP MTU (bytes)',1500,1280,9000)
 ],
 compute(input){
  const p={...input,dns:input.dns!==false,ready:input.ready!==false,egress:input.egress!==false,ingress:input.ingress!==false,underlay:+(input.underlay||1500)};
  const nodes=['Client Pod / Node A','Cluster DNS / Service','Underlay / Node B','Backend Pod'];
  const metrics=(delivery)=>[['Service flow','10.244.1.8:51000 → 10.96.0.25:80'],['Endpoint flow','10.244.1.8:51000 → 10.244.2.17:8080'],['Required underlay IP MTU','1500'],['Delivery',delivery?'YES':'NO']];
  const limit=pair('One declared Linux VXLAN teaching deployment: Service translation occurs before encapsulation and preserves the client source IP. Kubernetes allows other Service and CNI implementations, tunnel overheads and source-NAT behavior; this is a mechanism model, not kube-proxy or CNI emulation.','ஒரு declared Linux VXLAN teaching deployment: Service translation encapsulation-க்கு முன் நடந்து client source IP-ஐ preserve செய்கிறது. Kubernetes வேறு Service/CNI implementations, tunnel overheads, source-NAT behavior-ஐ அனுமதிக்கிறது; இது mechanism model, kube-proxy அல்லது CNI emulation அல்ல.');
  const e=[event(p.dns?'Resolve the Service name':'DNS query is blocked',p.dns?'Service name-ஐ resolve செய்கிறது':'DNS query block ஆகிறது',p.dns?'At t=0 ms, UDP 10.244.1.8:53000→10.96.0.10:53 asks for catalog.default.svc.cluster.local A and receives ClusterIP 10.96.0.25. DNS returns the Service identity, not the selected Pod.':'At t=0 ms, client egress policy blocks UDP/53 before the Service lookup. No TCP SYN for the ClusterIP can be formed from this name.',p.dns?'t=0 ms-ல் UDP 10.244.1.8:53000→10.96.0.10:53, catalog.default.svc.cluster.local A-ஐ கேட்டு ClusterIP 10.96.0.25 பெறுகிறது. DNS selected Pod அல்ல, Service identity-ஐ தருகிறது.':'t=0 ms-ல் client egress policy UDP/53-ஐ Service lookup-க்கு முன் block செய்கிறது. இந்த name-இலிருந்து ClusterIP TCP SYN உருவாகாது.',0,1,p.dns?{timeMs:0,transport:'UDP',tuple:'10.244.1.8:53000→10.96.0.10:53',query:'catalog.default.svc.cluster.local A',answer:'10.96.0.25',TTLSeconds:30}:{timeMs:0,delivered:false,failureGate:'DNS_POLICY',serviceSynSent:false},!p.dns)];
  if(!p.dns)return{nodes,events:e,metrics:metrics(false),limit};
  e.push(event(p.ready?'Select a ready EndpointSlice endpoint':'No ready endpoint can be selected',p.ready?'Ready EndpointSlice endpoint தேர்வு':'Ready endpoint தேர்வு செய்ய முடியாது',p.ready?'At t=10 ms, the Service data plane matches TCP 10.244.1.8:51000→10.96.0.25:80. EndpointSlice offers ready=true endpoint 10.244.2.17 with targetPort 8080, so destination NAT changes only destination IP and port.':'At t=10 ms, DNS and ClusterIP are valid, but EndpointSlice has no ready=true endpoint. A Service address does not create an application receiver by itself.',p.ready?'t=10 ms-ல் Service data plane TCP 10.244.1.8:51000→10.96.0.25:80-ஐ match செய்கிறது. EndpointSlice ready=true endpoint 10.244.2.17, targetPort 8080 தருவதால் destination NAT destination IP மற்றும் port மட்டும் மாற்றுகிறது.':'t=10 ms-ல் DNS மற்றும் ClusterIP சரி; ஆனால் EndpointSlice-ல் ready=true endpoint இல்லை. Service address தனியாக application receiver உருவாக்காது.',0,1,p.ready?{timeMs:10,originalTuple:'10.244.1.8:51000→10.96.0.25:80',EndpointSlice:'10.244.2.17:8080',ready:true,translatedTuple:'10.244.1.8:51000→10.244.2.17:8080',translation:'DNAT destination only'}:{timeMs:10,delivered:false,failureGate:'NO_READY_ENDPOINT',readyEndpoints:0,clusterIP:'10.96.0.25'},!p.ready));
  if(!p.ready)return{nodes,events:e,metrics:metrics(false),limit};
  e.push(event(p.egress?'Client egress policy permits the flow':'Client egress policy drops the flow',p.egress?'Client egress policy flow-ஐ permit செய்கிறது':'Client egress policy flow-ஐ drop செய்கிறது',p.egress?'At t=12 ms, the selected client policy permits TCP from pod label role=frontend to destination label app=catalog on port 8080. NetworkPolicy decisions apply to the translated backend flow in this deployment.':'At t=12 ms, an egress-isolated client has no selected allow rule for the backend tuple. Destination ingress permission cannot override this source-side denial.',p.egress?'t=12 ms-ல் selected client policy, pod label role=frontend-இலிருந்து destination label app=catalog-க்கு TCP port 8080 permit செய்கிறது. இந்த deployment-ல் NetworkPolicy decision translated backend flow-க்கு பொருந்துகிறது.':'t=12 ms-ல் egress-isolated client-க்கு backend tuple-ஐ allow செய்யும் selected rule இல்லை. Destination ingress permission இந்த source-side denial-ஐ override செய்யாது.',0,1,p.egress?{timeMs:12,direction:'EGRESS',protocol:'TCP',destinationPort:8080,sourceLabel:'role=frontend',destinationLabel:'app=catalog',decision:'ALLOW'}:{timeMs:12,delivered:false,failureGate:'SOURCE_EGRESS_POLICY',translatedTuple:'10.244.1.8:51000→10.244.2.17:8080',decision:'DROP'},!p.egress));
  if(!p.egress)return{nodes,events:e,metrics:metrics(false),limit};
  e.push(event(p.ingress?'Backend ingress policy permits the flow':'Backend ingress policy drops the flow',p.ingress?'Backend ingress policy flow-ஐ permit செய்கிறது':'Backend ingress policy flow-ஐ drop செய்கிறது',p.ingress?'At t=13 ms, the policies selecting app=catalog additively permit ingress from role=frontend on TCP/8080. Both source egress and destination ingress now allow this connection.':'At t=13 ms, the destination is ingress-isolated and no selected policy permits this source and TCP/8080. Source egress permission alone is insufficient.',p.ingress?'t=13 ms-ல் app=catalog-ஐ select செய்யும் policies, role=frontend-இலிருந்து TCP/8080 ingress-ஐ additively permit செய்கின்றன. Source egress மற்றும் destination ingress இரண்டும் இப்போது allow செய்கின்றன.':'t=13 ms-ல் destination ingress-isolated; இந்த source மற்றும் TCP/8080-ஐ permit செய்யும் selected policy இல்லை. Source egress permission மட்டும் போதாது.',1,2,p.ingress?{timeMs:13,direction:'INGRESS',protocol:'TCP',destinationPort:8080,policyCombination:'additive union',decision:'ALLOW'}:{timeMs:13,delivered:false,failureGate:'DESTINATION_INGRESS_POLICY',decision:'DROP'},!p.ingress));
  if(!p.ingress)return{nodes,events:e,metrics:metrics(false),limit};
  const fits=p.underlay>=1500;
  e.push(event('Encapsulate the translated Pod packet','Translated Pod packet-ஐ encapsulate செய்கிறது','At t=15 ms, Node A wraps the 1450-byte inner IP packet plus 14-byte inner Ethernet, 8-byte VXLAN, 8-byte UDP and 20-byte outer IPv4. Outer IP length is 1500 bytes: UDP 55000→4789, VNI 4096, 192.0.2.11→192.0.2.12, TTL 64.','t=15 ms-ல் Node A, 1450-byte inner IP packet, 14-byte inner Ethernet, 8-byte VXLAN, 8-byte UDP, 20-byte outer IPv4-ஐ wrap செய்கிறது. Outer IP length 1500 bytes: UDP 55000→4789, VNI 4096, 192.0.2.11→192.0.2.12, TTL 64.',0,2,{timeMs:15,innerIPLength:1450,innerEthernet:14,VXLAN:8,UDP:8,outerIPv4:20,requiredOuterIPMTU:1500,VNI:4096,outerUDP:'55000→4789',outerIP:'192.0.2.11→192.0.2.12',outerTTL:64,innerTuple:'10.244.1.8:51000→10.244.2.17:8080'}));
  e.push(event(fits?'Route the tunnel packet':'Underlay MTU drops the tunnel packet',fits?'Tunnel packet-ஐ route செய்கிறது':'Underlay MTU tunnel packet-ஐ drop செய்கிறது',fits?'At t=16 ms, the underlay router removes the received outer Ethernet header, decrements only the outer IPv4 TTL 64→63 and writes next-hop outer MAC addresses. VNI and inner Pod tuple remain unchanged.':`At t=16 ms, required outer IP length 1500 exceeds underlay MTU ${p.underlay}. The modeled packet is not fragmented; correct Pod MTU or restore the underlay budget.`,fits?'t=16 ms-ல் underlay router received outer Ethernet header-ஐ நீக்கி outer IPv4 TTL மட்டும் 64→63 குறைத்து next-hop outer MAC addresses எழுதுகிறது. VNI மற்றும் inner Pod tuple மாறாது.':`t=16 ms-ல் required outer IP length 1500, underlay MTU ${p.underlay}-ஐ மீறுகிறது. Modeled packet fragment ஆகாது; Pod MTU-ஐ சரிசெய்யவும் அல்லது underlay budget-ஐ restore செய்யவும்.`,2,2,fits?{timeMs:16,outerEthernetBefore:'node-a-mac→router-in-mac',outerEthernetAfter:'router-out-mac→node-b-mac',outerTTL:63,innerTupleChanged:false,VNI:4096}:{timeMs:16,delivered:false,failureGate:'OVERLAY_MTU',requiredMTU:1500,configuredMTU:p.underlay},!fits));
  if(!fits)return{nodes,events:e,metrics:metrics(false),limit};
  e.push(event('Decapsulate and deliver to targetPort','Decapsulate செய்து targetPort-க்கு deliver செய்கிறது','At t=17 ms, Node B validates VNI 4096, removes outer Ethernet/IPv4/UDP/VXLAN and delivers TCP 10.244.1.8:51000→10.244.2.17:8080. The application observes the client Pod source in this declared path.','t=17 ms-ல் Node B VNI 4096-ஐ validate செய்து outer Ethernet/IPv4/UDP/VXLAN-ஐ நீக்கி TCP 10.244.1.8:51000→10.244.2.17:8080-ஐ deliver செய்கிறது. இந்த declared path-ல் application client Pod source-ஐப் பார்க்கிறது.',2,3,{timeMs:17,decapsulated:true,removedHeaders:['outer Ethernet','outer IPv4','UDP','VXLAN'],deliveredTuple:'10.244.1.8:51000→10.244.2.17:8080',targetPort:8080}));
  e.push(event('Return the backend response through the reverse tunnel','Backend response-ஐ reverse tunnel வழியாகத் திருப்புகிறது','At t=30 ms, the backend replies 10.244.2.17:8080→10.244.1.8:51000. Node B uses VXLAN VNI 4096 with outer 192.0.2.12→192.0.2.11; Node A decapsulates and connection tracking presents the reply for the original Service conversation.','t=30 ms-ல் backend 10.244.2.17:8080→10.244.1.8:51000 reply செய்கிறது. Node B VXLAN VNI 4096, outer 192.0.2.12→192.0.2.11 பயன்படுத்துகிறது; Node A decapsulate செய்து connection tracking original Service conversation-க்கு reply-ஐ வழங்குகிறது.',3,0,{timeMs:30,backendReply:'10.244.2.17:8080→10.244.1.8:51000',reverseOuterIP:'192.0.2.12→192.0.2.11',VNI:4096,clientConversation:'10.96.0.25:80→10.244.1.8:51000',HTTPStatus:200,delivered:true}));
  return{nodes,events:e,metrics:metrics(true),limit};
 }
};
